package mg.lagrace.api.dashboard.web;

import mg.lagrace.api.dashboard.dto.dashboard.DashboardDtos;
import java.time.LocalDate; import mg.lagrace.api.shared.api.ApiResponse; import mg.lagrace.api.dashboard.dto.dashboard.DashboardDtos.*; import mg.lagrace.api.dashboard.application.DashbordService; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/dashboard") public class DashbordController { private final DashbordService service; public DashbordController(DashbordService service){this.service=service;} private void finances(Authentication a){if(a==null||a.getAuthorities().stream().noneMatch(x->"ROLE_DROIT_FINANCES".equals(x.getAuthority())))throw new AccessDeniedException("DROIT_FINANCES requis");}
 @GetMapping("/cards") public ApiResponse<Cards> cards(@RequestParam(required=false) LocalDate date,Authentication a){finances(a);return ApiResponse.success(service.cards(date));} @GetMapping("/arrivals") public ApiResponse<?> arrivals(@RequestParam(required=false) LocalDate date){return ApiResponse.success(service.arrivals(date));} @GetMapping("/departures") public ApiResponse<?> departures(@RequestParam(required=false) LocalDate date){return ApiResponse.success(service.departures(date));} @GetMapping("/events") public ApiResponse<?> events(@RequestParam(required=false) LocalDate date,@RequestParam(defaultValue="7") int days){return ApiResponse.success(service.events(date,Math.min(30,Math.max(1,days))));} @GetMapping("/tasks") public ApiResponse<Tasks> tasks(@RequestParam(required=false) LocalDate date){return ApiResponse.success(service.tasks(date));} @GetMapping("/cash") public ApiResponse<Cash> cash(@RequestParam(required=false) LocalDate date,Authentication a){finances(a);return ApiResponse.success(service.cash(date));} @GetMapping("/rooms-live") public ApiResponse<?> rooms(@RequestParam(required=false) LocalDate date){return ApiResponse.success(service.roomsLive(date));} @GetMapping("/spaces-live") public ApiResponse<?> spaces(@RequestParam(required=false) LocalDate date){return ApiResponse.success(service.spacesLive(date));} @GetMapping("/free-rooms") public ApiResponse<?> freeRooms(@RequestParam(required=false) LocalDate date){return ApiResponse.success(service.freeRooms(date));} @GetMapping("/month") public ApiResponse<Month> month(@RequestParam(required=false) LocalDate date,Authentication a){finances(a);return ApiResponse.success(service.month(date));}}
